import type { SettingValue } from "../../../types/settings-presets/SettingsPreset";
import { cloneSettingValue } from "./values";

/** Like campaign settings sources, each filename is a namespace and each key is literal. */
export function parseSettingsPresetSources(
  files: Record<string, unknown>,
): Record<string, Record<string, SettingValue>> {
  return Object.fromEntries(
    Object.entries(files).map(([path, source]) => {
      const filename = path.slice(path.lastIndexOf("/") + 1);
      if (!/^[a-zA-Z0-9][a-zA-Z0-9._-]*\.json$/.test(filename))
        throw new Error(`Invalid settings preset namespace filename: ${path}`);
      if (!source || typeof source !== "object" || Array.isArray(source))
        throw new Error(`Settings preset ${path} must be an object of setting values.`);
      const values = Object.fromEntries(
        Object.entries(source).map(([key, value]) => {
          if (!key.trim())
            throw new Error(`Settings preset ${path} contains an empty setting key.`);
          return [key, cloneSettingValue(value)];
        }),
      );
      return [filename.slice(0, -5), values];
    }),
  );
}
