import type { SettingsPreset } from "../../../../types/settings-presets/SettingsPreset";
import { MODULE_ID } from "../../../constants";
import { notifyError } from "../../notifications/notify-user";
import { reviewPreferences } from "../preset-runtime/review";
import { escapePresetHtml } from "../preset-runtime/presentation";
import { isPresetEnabled, presetEntries } from "./engine";
export function presetTitle(preset: SettingsPreset): string {
  return preset.title ?? game?.modules.get(preset.namespace)?.title ?? preset.namespace;
}
export function presetIgnoreSetting(preset: SettingsPreset): string {
  return preset.ignoreSetting ?? `ignoreSettingsPreset-${preset.namespace}`;
}
export function reportPresetError(error: unknown): void {
  notifyError(
    escapePresetHtml(
      `Settings preset could not be completed: ${error instanceof Error ? error.message : String(error)}`,
    ),
    error,
  );
}
export async function applyAndReportSettingsPreset(preset: SettingsPreset): Promise<void> {
  if (!isPresetEnabled(preset)) throw new Error("Preset is not active.");
  await reviewPreferences({
    owner: MODULE_ID,
    title: presetTitle(preset),
    entries: () => presetEntries(preset),
    ...(preset.description ? { description: preset.description } : {}),
  });
}
export async function promptSettingsPreset(
  preset: SettingsPreset,
  dependencyChanged = false,
): Promise<void> {
  if (
    !isPresetEnabled(preset) ||
    game?.system.id !== "wfrp4e" ||
    (preset.promptOnStartup === false && !dependencyChanged)
  )
    return;
  await reviewPreferences({
    owner: MODULE_ID,
    title: presetTitle(preset),
    entries: () => presetEntries(preset),
    startup: true,
    ignoreKey: presetIgnoreSetting(preset),
    ...(preset.description ? { description: preset.description } : {}),
  });
}
