import { MODULE_ID } from "../../../constants";
import { CONFLICT_SETTING, settingsPresetCoordinator } from "./coordinator";
export function registerPresetConflicts(): void {
  Hooks.once("setup", () => {
    game?.settings.register(MODULE_ID, CONFLICT_SETTING, {
      name: "Settings preset conflict choices",
      hint: "Preferred sources for conflicting settings presets.",
      scope: "world",
      config: false,
      default: {},
      type: Object,
    });
    game?.settings.registerMenu(MODULE_ID, "resetPresetConflictChoices", {
      name: "Settings preset conflicts",
      label: "Reset Conflict Choices",
      hint: "Forget preferred sources and review conflicts again the next time presets are checked or applied.",
      icon: "fa-solid fa-code-compare",
      restricted: true,
      type: class extends foundry.applications.api.ApplicationV2 {
        override async render(): Promise<this> {
          if (!game?.ready || !game.user?.isGM) throw new Error("A ready GM session is required.");
          const confirmed = await foundry.applications.api.DialogV2.wait({
            window: { title: "Reset Preset Conflict Choices?" },
            content:
              "<p>Forget saved conflict choices? Current world settings will remain unchanged.</p>",
            buttons: [
              { action: "reset", label: "Reset Choices" },
              { action: "cancel", label: "Cancel", default: true },
            ],
            rejectClose: false,
          });
          if (confirmed === "reset") await settingsPresetCoordinator.reset();
          return this;
        }
      },
    });
  });
}
