import type {
  SettingsPreset,
  PresetInspection,
  PresetResult,
} from "../../../../types/settings-presets/SettingsPreset";
import { MODULE_ID } from "../../../constants";
import {
  inspectPreferences,
  applyPreferences,
  isSettingsNamespaceActive,
} from "../preset-runtime/engine";
export function isPresetEnabled(preset: SettingsPreset): boolean {
  return isSettingsNamespaceActive(preset.namespace) && (preset.enabled?.() ?? true);
}
export function presetEntries(preset: SettingsPreset) {
  if (!isPresetEnabled(preset)) throw new Error("Preset is not active.");
  return [
    ...Object.entries(preset.values).map(([key, value]) => ({
      namespace: preset.namespace,
      key,
      value,
    })),
    ...(preset.additionalSettings?.() ?? []),
  ];
}
export function inspectSettingsPreset(preset: SettingsPreset): PresetInspection {
  if (!isPresetEnabled(preset))
    return {
      changes: [],
      unavailable: [`${preset.namespace}: system, module, or integration is not active`],
    };
  const result = inspectPreferences(MODULE_ID, presetEntries(preset));
  return {
    changes: result.changes.map((change) => ({ ...change, requiresReload: result.requiresReload })),
    unavailable: [...result.skipped, ...result.failed, ...result.conflicts].map(
      (issue) => `${issue.id}: ${issue.reason}`,
    ),
  };
}
export async function applySettingsPreset(preset: SettingsPreset): Promise<PresetResult> {
  if (!game?.ready || !game.user?.isGM)
    throw new Error("A ready GM session is required to apply settings presets.");
  if (!isPresetEnabled(preset)) throw new Error("Preset is not active.");
  const result = await applyPreferences(MODULE_ID, presetEntries(preset));
  if (result.blocked || result.failed.length)
    throw new Error(
      `${result.updated.length} settings updated. ${[...result.skipped, ...result.failed, ...result.conflicts].map((issue) => `${issue.id}: ${issue.reason}`).join("; ")}${result.missingTables.length ? ` Missing rule tables: ${result.missingTables.join(", ")}` : ""}`,
    );
  return result;
}
