import { MODULE_ID } from "../../constants";

export const WFRP_IMPORTED_TIDY_SETTING = "keepWfrpImportedContentTidy";
export const WFRP_COMPENDIUM_TIDY_SETTING = "keepWfrpCompendiumsTidy";
export const WFRP_TIDY_SETTINGS = [
  WFRP_IMPORTED_TIDY_SETTING,
  WFRP_COMPENDIUM_TIDY_SETTING,
] as const;

export function registerWfrpTidySettings(onChange: () => void): void {
  if (!game?.user) throw new Error("Foundry user is unavailable during WFRP setting registration.");
  for (const key of WFRP_TIDY_SETTINGS) {
    game.settings.register(MODULE_ID, key, {
      name: `${MODULE_ID}.Settings.WfrpFolders.${key}.Name`,
      hint: `${MODULE_ID}.Settings.WfrpFolders.${key}.Hint`,
      config: game.user.isGM === true,
      default: true,
      scope: "world",
      type: Boolean,
      onChange,
    });
  }
}
