import type { SettingsPresetApi } from "../../../../types/settings-presets/Protocol";
import { MODULE_ID } from "../../../constants";
import { getSettingsPresets, getSettingsPreset } from "./definitions";
import { presetEntries, isPresetEnabled } from "./engine";
import { presetTitle } from "./interface";
import { inspectPreferences, applyPreferences } from "../preset-runtime/engine";
import { resolvePreferences } from "../preset-runtime/coordination";
import { captureSettings } from "../preset-runtime/export";
function entries(namespace?: string) {
  const presets =
    namespace === undefined
      ? getSettingsPresets().filter(isPresetEnabled)
      : [getSettingsPreset(namespace)];
  if (presets.some((preset) => !isPresetEnabled(preset))) throw new Error("Preset is not active.");
  return presets.flatMap(presetEntries);
}
export const settingsPresetsApi: SettingsPresetApi = {
  version: 1,
  getPresets: () =>
    getSettingsPresets()
      .filter(isPresetEnabled)
      .map((preset) => ({
        namespace: preset.namespace,
        title: presetTitle(preset),
        entries: presetEntries(preset),
      })),
  inspect: (namespace) => inspectPreferences(MODULE_ID, entries(namespace)),
  apply: async (namespace) => applyPreferences(MODULE_ID, entries(namespace)),
  resolve: async (namespace) => resolvePreferences(MODULE_ID, entries(namespace)),
  capture: captureSettings,
};
