import type { TidyEntry, TidyFolder, TidyPlan } from "../../../types/wfrp/Folders";

/** Only the official publisher's WFRP modules qualify, not every WFRP extension. */
export function isOfficialWfrpModule(id: string, authors: Iterable<{ name: string }>): boolean {
  return id.startsWith("wfrp4e-") && [...authors].some((a) => /cubicle\s*7/i.test(a.name));
}

/** Current Warhammer imports, legacy imports, and native compendium imports. */
export function officialSource(
  flags: Record<string, unknown>,
  compendiumSource: string | null | undefined,
  officialPackages: ReadonlySet<string>,
): string | undefined {
  const warhammer = flags["warhammer-lib"] as { source?: string } | undefined;
  const core = flags["core"] as { sourceId?: string } | undefined;
  const candidates = [
    warhammer?.source,
    flags["source"],
    compendiumSource?.startsWith("Compendium.") ? compendiumSource.split(".")[1] : undefined,
    core?.sourceId?.startsWith("Compendium.") ? core.sourceId.split(".")[1] : undefined,
  ];
  // Older WFRP initializers identified the module in its initialization-folder flag.
  for (const [id, value] of Object.entries(flags)) {
    if (value && typeof value === "object" && "initialization-folder" in value) candidates.push(id);
  }
  return candidates.find((id): id is string => typeof id === "string" && officialPackages.has(id));
}

/** Keep the first levels; join overflowing names literally with slashes. */
export function fitFolderPath(path: string[], availableDepth: number): string[] {
  if (availableDepth < 1) throw new Error("WFRP folders need at least one available level.");
  if (path.length <= availableDepth) return [...path];
  return [...path.slice(0, availableDepth - 1), path.slice(availableDepth - 1).join("/")];
}

/** Plan without mutating live documents. Mixed folders never move campaign content. */
export function planWfrpTidy(
  folders: TidyFolder[],
  entries: TidyEntry[],
  rootId: string,
  maxDepth: number,
): TidyPlan {
  const byId = new Map(folders.map((f) => [f.id, f]));
  const ancestry = (id: string | null): TidyFolder[] => {
    const path: TidyFolder[] = [];
    while (id) {
      if (path.some((f) => f.id === id)) throw new Error("Cycle in the WFRP folder hierarchy.");
      const folder = byId.get(id);
      if (!folder) break;
      path.unshift(folder);
      id = folder.parent;
    }
    return path;
  };
  const underRoot = (id: string | null) => ancestry(id).some((f) => f.id === rootId);
  const children = (id: string) => folders.filter((f) => f.parent === id);
  const clean = (folder: TidyFolder): boolean => {
    const direct = entries.filter((e) => e.parent === folder.id);
    const nested = children(folder.id);
    return (
      (folder.official || direct.some((e) => e.official) || nested.length > 0) &&
      direct.every((e) => e.official) &&
      nested.every((f) => f.id !== rootId && clean(f))
    );
  };
  // Validate ancestry before recursively classifying subtrees.
  for (const folder of folders) ancestry(folder.id);
  const candidates = folders.filter((f) => !underRoot(f.id) && clean(f));
  const candidateIds = new Set(candidates.map((f) => f.id));
  const branches = candidates.filter(
    (f) => !ancestry(f.parent).some((a) => candidateIds.has(a.id)),
  );
  const plan: TidyPlan = { folders: [], entries: [] };
  const moved = new Set<string>();
  for (const branch of branches) {
    const subtree = folders
      .map((folder) => ({ folder, path: ancestry(folder.id) }))
      .filter(({ path }) => path.some((f) => f.id === branch.id))
      .map(({ folder, path }) => ({
        folder,
        path: path.slice(path.findIndex((f) => f.id === branch.id)),
      }))
      .sort((a, b) => b.path.length - a.path.length);
    for (const { folder, path } of subtree) {
      moved.add(folder.id);
      const name = fitFolderPath(
        path.map((f) => f.name),
        maxDepth - 1,
      ).at(-1)!;
      const parent =
        path.length === 1 || maxDepth === 2
          ? rootId
          : path[Math.min(path.length - 2, maxDepth - 3)]!.id;
      if (folder.parent !== parent || folder.name !== name)
        plan.folders.push({ id: folder.id, parent, name });
    }
  }
  for (const entry of entries) {
    if (!entry.official || underRoot(entry.parent) || (entry.parent && moved.has(entry.parent)))
      continue;
    const path = ancestry(entry.parent).map((f) => f.name);
    plan.entries.push({
      id: entry.id,
      path: fitFolderPath(
        path.length ? path : (entry.fallbackPath ?? [entry.fallback]),
        maxDepth - 1,
      ),
    });
  }
  return plan;
}
