import { isItemAllowedInPaperDollSlot } from "./wfrp-equipment";
import { isWfrpOwnedItem } from "./wfrp-runtime-types";

// Keep the legacy marker so older Paper Doll compatibility versions cannot wrap this API twice.
const PATCH_MARKER = Symbol.for("paper-doll-wfrp4e.slot-type-filter");

type PaperDollFilterItems = (
  this: unknown,
  items: unknown[],
  slotId: string,
  slotIndex: number,
) => unknown[];

type PaperDollPrototype = Record<PropertyKey, unknown>;

function getPaperDollPrototype(): PaperDollPrototype | null {
  const paperDoll = (
    globalThis as {
      ui?: {
        paperDoll?: {
          prototype?: PaperDollPrototype;
        };
      };
    }
  ).ui?.paperDoll;

  return paperDoll?.prototype ?? null;
}

function assertPaperDollFilterApi(
  prototype: PaperDollPrototype | null,
  currentFilter: unknown,
): asserts prototype is PaperDollPrototype {
  if (!prototype || typeof currentFilter !== "function") {
    throw new Error("Paper Doll's required filterItems integration API is unavailable.");
  }
}

/**
 * Paper Doll exposes item filtering as an application method but does not
 * offer a pre-drop hook. Wrap that method so invalid WFRP4e equipment is
 * rejected before Paper Doll changes its actor flag or item state.
 */
export function enforcePaperDollSlotTypes(): void {
  const prototype = getPaperDollPrototype();
  const currentFilter = prototype?.["filterItems"];

  assertPaperDollFilterApi(prototype, currentFilter);

  // The ready hook can run again during a Foundry lifecycle refresh. The
  // marker is set only after this exact wrapper has been installed.
  if (prototype[PATCH_MARKER] === true) {
    return;
  }

  const originalFilter = currentFilter as PaperDollFilterItems;

  prototype["filterItems"] = function filterItems(
    this: unknown,
    items: unknown[],
    slotId: string,
    slotIndex: number,
  ): unknown[] {
    return originalFilter
      .call(this, items, slotId, slotIndex)
      .filter((item) => isWfrpOwnedItem(item) && isItemAllowedInPaperDollSlot(item, slotId));
  };
  prototype[PATCH_MARKER] = true;
}
