import { queueFolderTidy } from "./queue";
import { normalizeWfrpFolders } from "./merge";
import type { FoundryGame } from "../../../types/foundry";
import type { WfrpTidyFolder, WfrpTidyDocument } from "../../../types/wfrp/Folders";
import { MODULE_ID } from "../../constants";
import {
  fitFolderPath,
  isOfficialWfrpModule,
  officialSource,
  planWfrpTidy,
} from "../../functions/wfrp/folders";
import { WFRP_COMPENDIUM_TIDY_SETTING, WFRP_IMPORTED_TIDY_SETTING } from "./settings";
import { migrateWfrpTidySettings } from "./migration";
import { wfrpFolderDefaults, wfrpFolderName } from "../../functions/wfrp/folder-defaults";

const ROOT = "__wfrp_tidy_root__";
const ROOT_NAME = "Warhammer Fantasy Roleplay";

/** GM-callable operation, also used by the active-GM event handler. */
export async function tidyWfrpContent(currentGame: FoundryGame, maxDepth: number): Promise<void> {
  await queueFolderTidy(currentGame, () => runWfrpTidy(currentGame, maxDepth));
}

async function runWfrpTidy(currentGame: FoundryGame, maxDepth: number): Promise<void> {
  if (!currentGame.ready || !currentGame.user?.isGM || currentGame.system.id !== "wfrp4e") return;
  await migrateWfrpTidySettings(currentGame);
  const official = new Set(
    [...currentGame.modules.entries()]
      .filter(([id, module]) => isOfficialWfrpModule(id, module.authors ?? []))
      .map(([id]) => id),
  );
  official.add("wfrp4e");
  const source = (doc: WfrpTidyDocument) =>
    officialSource(doc.flags ?? {}, doc._stats?.compendiumSource, official);
  const titles = new Map([...currentGame.modules.entries()].map(([id, m]) => [id, m.title ?? id]));
  const defaults = wfrpFolderDefaults([
    ["wfrp4e", currentGame.system.packFolders ?? []],
    ...[...currentGame.modules.entries()]
      .filter(([id]) => official.has(id))
      .map(([id, module]): [string, NonNullable<typeof module.packFolders>] => [
        id,
        module.packFolders ?? [],
      ]),
  ]);

  const tidyDirectory = async (type: string, documents: WfrpTidyDocument[]) => {
    const folders = [...currentGame.folders].filter((f) => f.type === type);
    // Merge managed containers before planning any new imports.
    const occupied = new Set([...folders, ...documents].map((d) => d.folder?.id));
    const roots = folders
      .filter((f) => !f.folder && (f.name === ROOT_NAME || f.name === "WFRP"))
      .sort(
        (a, b) =>
          Number(occupied.has(b.id)) - Number(occupied.has(a.id)) || a.id.localeCompare(b.id),
      );
    let root = roots[0];
    await normalizeWfrpFolders(roots, folders, documents, (doc) => !!source(doc));
    // Rename the surviving legacy root even when its contents already need no moves.
    if (root && root.name !== ROOT_NAME) await root.update({ name: ROOT_NAME });
    const plan = planWfrpTidy(
      folders.map((f) => ({
        id: f.id,
        name: f.name,
        parent: f.folder?.id ?? null,
        official: !!source(f),
      })),
      documents.map((d) => ({
        id: d.id,
        parent: d.folder?.id ?? null,
        official: !!source(d),
        fallback: wfrpFolderName(titles.get(source(d)!) ?? "Content"),
        fallbackPath: type === "Compendium" ? defaults.packPaths.get(d.id) : undefined,
      })),
      root?.id ?? ROOT,
      maxDepth,
    );
    if (!root && !plan.folders.length && !plan.entries.length) return;
    const create = async (name: string, parent: string | null, color?: string | null) => {
      const folder = await CONFIG.Folder.documentClass.create({
        name,
        type,
        folder: parent,
        sorting: "a",
        ...(color ? { color } : {}),
      });
      if (!folder) throw new Error(`Could not create ${type} folder ${name}.`);
      folders.push(folder);
      return folder;
    };
    root ??= await create(ROOT_NAME, null);
    // Deepest descendants move first, so wrapping a branch never exceeds the limit.
    for (const change of plan.folders) {
      const folder = folders.find((f) => f.id === change.id)!;
      await folder.update({
        name: change.name,
        folder: change.parent === ROOT ? root.id : change.parent,
      });
    }
    for (const entry of plan.entries) {
      let parent: WfrpTidyFolder = root;
      const document = documents.find((d) => d.id === entry.id)!;
      const sourceColors = new Map<string, string>();
      const ancestors: WfrpTidyFolder[] = [];
      for (let ancestor = document.folder; ancestor; ancestor = ancestor.folder) {
        ancestors.unshift(ancestor);
      }
      for (const [index, ancestor] of ancestors.entries()) {
        const name = fitFolderPath(
          ancestors.slice(0, index + 1).map((f) => f.name),
          maxDepth - 1,
        ).at(-1)!;
        if (ancestor.color != null)
          sourceColors.set(wfrpFolderName(name), ancestor.color.toString());
      }
      for (const name of entry.path) {
        const matches = folders
          .filter(
            (f) => wfrpFolderName(f.name) === wfrpFolderName(name) && f.folder?.id === parent.id,
          )
          .sort((a, b) => a.id.localeCompare(b.id));
        const cleanName = wfrpFolderName(name);
        parent =
          matches[0] ??
          (await create(
            cleanName,
            parent.id,
            defaults.colors.get(cleanName) ?? sourceColors.get(cleanName),
          ));
      }
      await document.update({ folder: parent.id });
    }
    // Also repair folders from earlier runs, including imports already beneath the root.
    const style = async (parent: WfrpTidyFolder) => {
      for (const folder of folders.filter((f) => f.folder?.id === parent.id)) {
        const name = wfrpFolderName(folder.name);
        const color = defaults.colors.get(name);
        const changes: Record<string, unknown> = {};
        if (name !== folder.name) changes["name"] = name;
        if (color && color.toLowerCase() !== folder.color?.toString().toLowerCase())
          changes["color"] = color;
        if (Object.keys(changes).length) await folder.update(changes);
        await style(folder);
      }
    };
    await style(root);
    await normalizeWfrpFolders([root], folders, documents, (doc) => !!source(doc));
  };

  if (currentGame.settings.get(MODULE_ID, WFRP_IMPORTED_TIDY_SETTING)) {
    for (const [type, collection] of currentGame.collections.entries()) {
      if (type === "Folder" || !collection.documentClass.schema.has("folder")) continue;
      await tidyDirectory(type, [...collection]);
    }
  }
  if (currentGame.settings.get(MODULE_ID, WFRP_COMPENDIUM_TIDY_SETTING)) {
    const packs = [...currentGame.packs.entries()];
    const documents: WfrpTidyDocument[] = packs.map(([id, pack]) => ({
      id,
      get folder() {
        return pack.folder;
      },
      flags: { source: pack.metadata?.packageName },
      update: async (changes) => {
        const folder =
          changes["folder"] === null
            ? null
            : [...currentGame.folders].find((f) => f.id === changes["folder"])!;
        await pack.setFolder(folder);
        return undefined;
      },
    }));
    await tidyDirectory("Compendium", documents);
  }
}

export async function tidyWfrpContentIfEnabled(): Promise<void> {
  if (!game) return;
  await tidyWfrpContent(game, CONST.FOLDER_MAX_DEPTH);
}
