import { parseSettingsPresetSources } from "../../../functions/settings-presets/sources";

/** Add a namespace JSON file here to bundle a preset without writing registration code. */
export const SETTINGS_PRESETS = parseSettingsPresetSources(
  import.meta.glob<unknown>("/src/settings/*.json", { eager: true, import: "default" }),
);

import { parsePresetMetadata } from "../../../functions/settings-presets/metadata";
export const PRESET_METADATA = parsePresetMetadata(
  Object.values(
    import.meta.glob<unknown>("/src/settings-presets.json", { eager: true, import: "default" }),
  )[0] ?? {},
  Object.keys(SETTINGS_PRESETS),
);
