import type {
  PresetConflict,
  PresetProposal,
  ConflictDecisions,
} from "../../../types/settings-presets/Conflicts";
import type {
  SettingPreference,
  SettingValue,
} from "../../../types/settings-presets/SettingsPreset";
import type { PreferencePlan } from "../../../types/settings-presets/Protocol";
import { sameSettingValue } from "./values";
function canonical(value: SettingValue): SettingValue {
  if (Array.isArray(value)) return value.map(canonical);
  if (value && typeof value === "object")
    return Object.fromEntries(
      Object.keys(value)
        .sort()
        .map((key) => [key, canonical(value[key]!)]),
    );
  return value;
}
export function findPresetConflicts(proposals: PresetProposal[]): PresetConflict[] {
  const grouped = new Map<string, PresetConflict>();
  for (const proposal of proposals)
    for (const entry of proposal.entries) {
      const id = `${entry.namespace}.${entry.key}`;
      const group = grouped.get(id) ?? {
        id,
        namespace: entry.namespace,
        key: entry.key,
        candidates: [],
        signature: "",
      };
      const existing = group.candidates.find((candidate) => candidate.source === proposal.source);
      if (existing && !sameSettingValue(existing.value, entry.value))
        throw new Error(`Preset ${proposal.source} proposes two values for ${id}.`);
      if (!existing)
        group.candidates.push({
          source: proposal.source,
          title: proposal.title,
          value: entry.value,
        });
      grouped.set(id, group);
    }
  return [...grouped.values()]
    .filter((group) =>
      group.candidates.some(
        (candidate) => !sameSettingValue(candidate.value, group.candidates[0]!.value),
      ),
    )
    .map((group) => {
      group.candidates.sort((a, b) => a.source.localeCompare(b.source));
      group.signature = JSON.stringify(
        group.candidates.map(({ source, value }) => [source, canonical(value)]),
      );
      return group;
    })
    .sort((a, b) => a.id.localeCompare(b.id));
}
export function planResolvedPreferences(
  entries: SettingPreference[],
  conflicts: PresetConflict[],
  decisions: ConflictDecisions,
): PreferencePlan {
  const plan: PreferencePlan = { entries: [], excluded: [], conflicts: [] };
  for (const entry of entries) {
    const id = `${entry.namespace}.${entry.key}`;
    const conflict = conflicts.find((conflict) => conflict.id === id);
    if (!conflict) {
      plan.entries.push(entry);
      continue;
    }
    const decision = Object.hasOwn(decisions, id) ? decisions[id] : undefined;
    if (
      !decision ||
      decision.signature !== conflict.signature ||
      (decision.source !== null &&
        !conflict.candidates.some((candidate) => candidate.source === decision.source))
    ) {
      plan.conflicts.push({
        id,
        reason: "Conflicting presets need a GM choice in Compatibility Box",
      });
      continue;
    }
    if (decision.source === null) {
      plan.excluded.push(id);
      continue;
    }
    plan.entries.push({
      ...entry,
      value: conflict.candidates.find((candidate) => candidate.source === decision.source)!.value,
    });
  }
  return plan;
}
