// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- Foundry actor flags are dynamic records supplied by the active system.
// @ts-nocheck -- This adapter owns validation and migration for dynamic Foundry actor flags.

import { MODULE_ID } from "../../../constants";
import { LEGACY_ARGON_ACTOR_FLAG_SCOPE } from "./constants";

const ARGON_ACTOR_CONFIG_FLAGS = ["skillVisibility", "spellVisibility", "switchEquip"];

function getLegacyArgonActorFlag(actor, flag) {
  return actor.flags?.[LEGACY_ARGON_ACTOR_FLAG_SCOPE]?.[flag];
}

export function getArgonActorFlag(actor, flag) {
  return actor.getFlag(MODULE_ID, flag) ?? getLegacyArgonActorFlag(actor, flag);
}

export async function migrateLegacyArgonActorFlags(actor) {
  const updates = {};

  for (const flag of ARGON_ACTOR_CONFIG_FLAGS) {
    if (actor.getFlag(MODULE_ID, flag) !== undefined) continue;

    const legacyValue = getLegacyArgonActorFlag(actor, flag);
    if (legacyValue !== undefined) {
      updates[`flags.${MODULE_ID}.${flag}`] = legacyValue;
    }
  }

  if (Object.keys(updates).length) {
    await actor.update(updates);
  }
}
