import type { BossBarConfiguration } from "../../../../types/integrations/bossbar/BossBar";
import { MODULE_ID } from "../../../constants";
import { applySettingsPreset } from "../../settings/presets/engine";
import { getSettingsPreset } from "../../settings/presets/definitions";
import { promptSettingsPreset } from "../../settings/presets/interface";
import { BOSS_BAR_MODULE_ID } from "./constants";

export function localizeBossBar(key: string): string {
  return game?.i18n.localize(`${MODULE_ID}.BossBar.${key}`) ?? key;
}

export function reportBossBarError(error: unknown): void {
  console.error(`${MODULE_ID} | Boss Bar integration failed.`, error);
  ui?.notifications?.error(localizeBossBar("Error"));
}

export function readBossBarConfiguration(): BossBarConfiguration {
  return {
    currentHpPath: game?.settings.get(BOSS_BAR_MODULE_ID, "currentHpPath") as string,
    maxHpPath: game?.settings.get(BOSS_BAR_MODULE_ID, "maxHpPath") as string,
    woundsSystem: game?.settings.get(BOSS_BAR_MODULE_ID, "woundsSystem") as boolean,
  };
}

export { usesUpInArms } from "./preset";

export async function configureBossBar(): Promise<BossBarConfiguration> {
  await applySettingsPreset(getSettingsPreset(BOSS_BAR_MODULE_ID));
  ui?.notifications?.info(localizeBossBar("Configured"));
  return readBossBarConfiguration();
}

export function promptBossBarSetup(): Promise<void> {
  return promptSettingsPreset(getSettingsPreset(BOSS_BAR_MODULE_ID));
}
