import type { RulerToken, TokenRulerInstance } from "../../../../types/patches/wfrp4e/TokenRuler";

const guardedPrototypes = new WeakSet<TokenRulerInstance>();
const reportedTokens = new WeakSet<RulerToken>();

export function guardActorlessTokenRuler(): boolean {
  const prototype = CONFIG.Token?.rulerClass?.prototype;
  const corePrototype = foundry.canvas?.placeables?.tokens?.TokenRuler?.prototype;
  if (
    !prototype ||
    !corePrototype ||
    prototype === corePrototype ||
    !Object.prototype.isPrototypeOf.call(corePrototype, prototype) ||
    typeof prototype._getSegmentStyle !== "function" ||
    typeof corePrototype._getSegmentStyle !== "function" ||
    guardedPrototypes.has(prototype)
  ) {
    return false;
  }

  const original = prototype._getSegmentStyle;
  const coreStyle = corePrototype._getSegmentStyle;
  prototype._getSegmentStyle = function (...args) {
    if (this.token.actor) return original.apply(this, args);

    // WFRP 9.6.4 dereferences actor.system in its gridless segment style. An actorless
    // token can reach this path regardless of what caused its actor to become unavailable.
    if (!reportedTokens.has(this.token)) {
      reportedTokens.add(this.token);
      const { uuid, actorId, actorLink } = this.token.document;
      console.warn("WFRP4e Compatibility Box | Token has no actor; using the core ruler style.", {
        tokenUuid: uuid,
        actorId,
        actorLink,
        worldActorExists: Boolean(actorId && game?.actors.get(actorId)),
      });
    }
    return coreStyle.apply(this, args);
  };
  guardedPrototypes.add(prototype);
  return true;
}
