import type {
  OptionalFeatureId,
  OptionalFeatureStatus,
} from "../../../types/module/OptionalFeature";
import { isOptionalFeatureEnabled } from "./is-optional-feature-enabled";
import { isOptionalFeatureAvailable, OPTIONAL_FEATURES } from "./optional-features";

export function getOptionalFeatureStatuses(): OptionalFeatureStatus[] {
  return (
    Object.entries(OPTIONAL_FEATURES) as [
      OptionalFeatureId,
      (typeof OPTIONAL_FEATURES)[OptionalFeatureId],
    ][]
  ).map(([id, feature]) => ({
    available: isOptionalFeatureAvailable(id),
    enabled: isOptionalFeatureEnabled(id),
    id,
    targetModuleId: feature.targetModuleIds[0],
    targetModuleIds: feature.targetModuleIds,
  }));
}
