import { MODULE_ID } from "../../../constants";
import { BOSS_BAR_MODULE_ID, BOSS_BAR_SETTINGS } from "./constants";
import { configureBossBar, localizeBossBar, reportBossBarError } from "./configuration";

export function registerBossBarSettings(): void {
  if (!game) return;
  for (const key of ["automatic", "stacked"] as const) {
    game.settings.register(MODULE_ID, BOSS_BAR_SETTINGS[key], {
      name: `${MODULE_ID}.BossBar.Settings.${key}.Name`,
      hint: `${MODULE_ID}.BossBar.Settings.${key}.Hint`,
      config: true,
      default: true,
      scope: "world",
      type: Boolean,
    });
  }
  game.settings.register(MODULE_ID, BOSS_BAR_SETTINGS.woundsStyle, {
    name: `${MODULE_ID}.BossBar.Settings.woundsStyle.Name`,
    hint: `${MODULE_ID}.BossBar.Settings.woundsStyle.Hint`,
    config: true,
    default: "default-grass",
    scope: "world",
    type: String,
    choices: () =>
      Object.fromEntries(
        (game?.settings.get(BOSS_BAR_MODULE_ID, "barStyles") as { id: string; name: string }[]).map(
          (style) => [style.id, style.name],
        ),
      ),
  });
}

export function injectBossBarSetupButton(root: HTMLElement): void {
  if (!game?.user?.isGM) return;
  const input = root.querySelector(`[name="${BOSS_BAR_MODULE_ID}.currentHpPath"]`);
  const group = input?.closest(".form-group");
  if (!group || root.querySelector("[data-wfrp-bossbar-setup]")) return;
  const container = root.ownerDocument.createElement("div");
  container.className = "form-group";
  container.dataset["wfrpBossbarSetup"] = "";
  const button = root.ownerDocument.createElement("button");
  button.type = "button";
  button.textContent = localizeBossBar("Configure");
  button.addEventListener("click", async () => {
    button.disabled = true;
    try {
      const configuration = await configureBossBar();
      for (const [key, value] of Object.entries(configuration)) {
        const field = root.querySelector<HTMLInputElement>(`[name="bossbar.${key}"]`);
        if (!field) continue;
        if (typeof value === "boolean") field.checked = value;
        else field.value = value;
      }
      const stacked = root.querySelector<HTMLInputElement>(
        `[name="${MODULE_ID}.${BOSS_BAR_SETTINGS.stacked}"]`,
      );
      if (stacked) stacked.checked = true;
    } catch (error) {
      reportBossBarError(error);
    } finally {
      button.disabled = false;
    }
  });
  container.append(button);
  group.insertAdjacentElement("beforebegin", container);
}
