import type { SettingValue } from "../../../../types/settings-presets/SettingsPreset";
import { cloneSettingValue } from "../../settings-presets/values";

export const HEALTH_ESTIMATE_TABLE_NAMES = {
  wounds: "Compatibility Box: WFRP Wounds",
  unconscious: "Compatibility Box: WFRP Unconscious",
  dead: "Compatibility Box: WFRP Dead",
} as const;

/** Native Health Estimate 36 tables; custom tables retain their relative order and priority. */
export function configureWfrpEstimations(current: SettingValue, upInArms: boolean): SettingValue[] {
  if (!Array.isArray(current) || !current.length)
    throw new Error(
      "Health Estimate must have a default estimation table before applying its preset.",
    );
  const tables = cloneSettingValue(current) as Record<string, SettingValue>[];
  for (const table of tables) {
    if (
      !table ||
      typeof table !== "object" ||
      Array.isArray(table) ||
      typeof table["name"] !== "string" ||
      !Array.isArray(table["estimates"]) ||
      !Array.isArray(table["actorTypes"]) ||
      !Array.isArray(table["statusEffects"])
    )
      throw new Error(
        "Health Estimate's estimation tables do not match the supported version 36 schema.",
      );
  }
  const managed = new Set<string>(Object.values(HEALTH_ESTIMATE_TABLE_NAMES));
  const [fallback, ...custom] = tables.filter((table) => !managed.has(table["name"] as string));
  if (
    !fallback ||
    (fallback["actorTypes"] as SettingValue[]).length ||
    (fallback["statusEffects"] as SettingValue[]).length
  )
    throw new Error("Health Estimate's first table must remain its unfiltered default table.");
  const actors = ["character", "npc", "creature"];
  const wounds = {
    name: HEALTH_ESTIMATE_TABLE_NAMES.wounds,
    ignoreColor: false,
    actorTypes: actors,
    statusEffects: [],
    estimates: [
      { value: 0, label: upInArms ? "Mortal Peril!" : "Unconscious" },
      { value: 25, label: upInArms ? "Desperate!" : "Clinging On..." },
      { value: 50, label: "Bloodied" },
      { value: 75, label: "Wounded" },
      { value: 99, label: "Grazed" },
      { value: 100, label: "Unharmed" },
    ],
  };
  const condition = (name: string, status: string, label: string) => ({
    name,
    ignoreColor: true,
    actorTypes: actors,
    statusEffects: [status],
    estimates: [{ value: 100, label }],
  });
  // Health Estimate uses the last matching table. Existing custom tables remain later, so
  // explicit actor/condition overrides keep their priority. A real Dead condition beats Unconscious.
  return [
    fallback,
    wounds,
    condition(HEALTH_ESTIMATE_TABLE_NAMES.unconscious, "unconscious", "Unconscious"),
    condition(HEALTH_ESTIMATE_TABLE_NAMES.dead, "dead", "Gone to Morr..."),
    ...custom,
  ];
}
