import { registerCalendarContent } from "../foundry/integrations/imperial-calendar/register-content";
import { registerTimekeepingIntegration } from "../foundry/integrations/simple-timekeeping/register-integration";
import { registerHealthEstimateIntegration } from "../foundry/integrations/health-estimate/register-integration";
import { registerModuleApi } from "../foundry/api/register-module-api";
import { registerBossBarIntegration } from "../foundry/integrations/bossbar/register-integration";
import { registerArgonCombatHudIntegration } from "../foundry/integrations/enhancedcombathud/register-integration";
import { registerPaperDollIntegration } from "../foundry/integrations/fvtt-paper-doll-ui/register-integration";
import { registerPaperDollArgonBridge } from "../foundry/integrations/paper-doll-argon/register-integration";
import { registerSettingsPresets } from "../foundry/settings/presets/register";
import { registerScenePackerIntegration } from "../foundry/integrations/scene-packer/register-integration";
import { registerFaNexusIntegration } from "../foundry/integrations/fa-nexus/register-integration";
import { applyWfrp4eCompatibilityPatches } from "../foundry/patches/wfrp4e/apply-compatibility-patches";
import { registerModuleSettings } from "../foundry/settings/register-module-settings";
import { registerWfrpTidyHooks, scheduleWfrpTidy } from "../wfrp/folders/hooks";
import { registerWfrpTidySettings } from "../wfrp/folders/settings";

export function registerModuleHooks(): void {
  // The setting controls depend on the current user's role, which is known at setup.
  Hooks.once("setup", () => registerWfrpTidySettings(scheduleWfrpTidy));
  registerWfrpTidyHooks();
  Hooks.once("canvasInit", registerHealthEstimateIntegration);
  Hooks.once("ready", registerHealthEstimateIntegration);
  Hooks.once("init", () => {
    applyWfrp4eCompatibilityPatches();
    registerModuleSettings();
    registerTimekeepingIntegration();
    registerCalendarContent();
    registerScenePackerIntegration();
    void registerFaNexusIntegration();
    registerModuleApi();
    registerBossBarIntegration();
    registerArgonCombatHudIntegration();
    registerPaperDollIntegration();
    registerPaperDollArgonBridge();
    registerSettingsPresets();
  });
}
