import type { WfrpActor, WfrpOwnedItem } from "../../../../types/patches/paper-doll/WfrpRuntime";

export type { WfrpActor, WfrpOwnedItem } from "../../../../types/patches/paper-doll/WfrpRuntime";

const WFRP_EQUIPMENT_ACTOR_TYPES = new Set(["character", "npc", "creature"]);

export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

export function isWfrpActor(value: unknown): value is WfrpActor {
  if (!isRecord(value)) {
    return false;
  }

  return (
    typeof value["getFlag"] === "function" &&
    value["items"] !== undefined &&
    typeof value["setFlag"] === "function" &&
    typeof value["type"] === "string" &&
    typeof value["uuid"] === "string"
  );
}

/** WFRP vehicles do not use the actor equipment model or handedness fields. */
export function isWfrpEquipmentActor(value: unknown): value is WfrpActor {
  return isWfrpActor(value) && WFRP_EQUIPMENT_ACTOR_TYPES.has(value.type);
}

export function isWfrpOwnedItem(value: unknown): value is WfrpOwnedItem {
  if (!isRecord(value)) {
    return false;
  }

  return (
    typeof value["id"] === "string" &&
    typeof value["name"] === "string" &&
    typeof value["type"] === "string" &&
    typeof value["update"] === "function" &&
    typeof value["uuid"] === "string"
  );
}
