import type { WfrpTidyDocument, WfrpTidyFolder } from "../../../types/wfrp/Folders";

/** Merge managed duplicates without deleting their contents; eject unrelated content to root. */
export async function normalizeWfrpFolders(
  roots: WfrpTidyFolder[],
  folders: WfrpTidyFolder[],
  documents: WfrpTidyDocument[],
  official: (document: WfrpTidyDocument) => boolean,
): Promise<void> {
  const children = (folder: WfrpTidyFolder) => folders.filter((f) => f.folder?.id === folder.id);
  const contents = (folder: WfrpTidyFolder) => documents.filter((d) => d.folder?.id === folder.id);
  const move = async (document: WfrpTidyDocument, parent: WfrpTidyFolder | null) => {
    await document.update({ folder: parent?.id ?? null });
    if ((document.folder?.id ?? null) !== (parent?.id ?? null))
      throw new Error(`Could not move WFRP folder content ${document.id}.`);
  };
  const merge = async (source: WfrpTidyFolder, target: WfrpTidyFolder) => {
    for (const document of contents(source)) await move(document, target);
    for (const child of children(source)) await move(child, target);
    const deleted = await source.delete({ deleteSubfolders: false, deleteContents: false });
    if (!deleted) throw new Error(`Could not delete empty duplicate WFRP folder ${source.name}.`);
    folders.splice(folders.indexOf(source), 1);
  };
  const hasOfficialContent = (folder: WfrpTidyFolder): boolean =>
    official(folder) ||
    contents(folder).some(official) ||
    children(folder).some(hasOfficialContent);
  const visit = async (parent: WfrpTidyFolder) => {
    const byName = new Map<string, WfrpTidyFolder>();
    for (const child of children(parent).sort((a, b) => a.id.localeCompare(b.id))) {
      const existing = byName.get(child.name);
      if (existing) await merge(child, existing);
      else byName.set(child.name, child);
    }
    for (const document of contents(parent)) {
      if (!official(document)) await move(document, null);
    }
    for (const child of children(parent)) {
      if (hasOfficialContent(child)) await visit(child);
      else await move(child, null);
    }
  };
  const root = roots[0];
  if (!root) return;
  for (const duplicate of roots.slice(1)) await merge(duplicate, root);
  await visit(root);
}
