import type { ActiveEffectModelClass } from "../../../../types/patches/wfrp4e/ActiveEffectModel";

function repairActiveEffectSchema(model: ActiveEffectModelClass): boolean {
  const schema = model.schema;
  if (schema.fields["changes"]) return false;

  const original = model.defineSchema;
  model.defineSchema = function () {
    const fields = original.call(this);
    if (!fields["changes"]) {
      fields["changes"] = foundry.data.ActiveEffectTypeDataModel.defineSchema()["changes"];
    }
    return fields;
  };

  // Foundry caches schema objects. Extend the existing object as well as future
  // definitions, using the same core field factory as its startup fallback.
  schema.extendFields({
    changes: foundry.data.ActiveEffectTypeDataModel.defineSchema()["changes"],
  });
  return true;
}

export function repairWfrpActiveEffectSchemas(): number {
  return Object.values(CONFIG.ActiveEffect?.dataModels ?? {}).reduce(
    (count, model) => count + Number(repairActiveEffectSchema(model)),
    0,
  );
}
