import { countsAsCritical } from "../../../functions/integrations/bossbar/health";
import type {
  BossBarEntry,
  BossBarHealth,
  BossCandidate,
} from "../../../../types/integrations/bossbar/BossBar";

interface BossItem {
  name: string;
  type: string;
  system?: { wounds?: { value?: unknown } };
}

export interface BossActor {
  uuid: string;
  hasPlayerOwner: boolean;
  items: Iterable<BossItem>;
  system: {
    status?: {
      wounds?: { value: number; max: number };
      criticalWounds?: { max: number };
    };
    characteristics?: { ws?: { value: number }; s?: { value: number } };
  };
}

export interface BossScene {
  getFlag: (scope: string, key: string) => BossBarEntry[] | undefined;
  setFlag: (scope: string, key: string, value: BossBarEntry[]) => Promise<unknown>;
}

export interface BossCombat {
  scene?: BossScene;
  combatants: Iterable<{
    actor?: BossActor;
    token?: { disposition: number };
  }>;
}

export interface BossBarApplication {
  id: string;
  element: HTMLElement;
  bars: { actor: BossActor }[];
  updateBars: () => void;
  render: (force: boolean) => Promise<unknown>;
}

export function getBossBarApplication(): BossBarApplication | undefined {
  return ui && (Reflect.get(ui, "bossBar") as BossBarApplication | undefined);
}

export function getBossCandidates(combat: BossCombat): BossCandidate[] {
  return Array.from(combat.combatants).flatMap(({ actor, token }) =>
    actor
      ? [
          {
            uuid: actor.uuid,
            enemy: token?.disposition === -1 && !actor.hasPlayerOwner,
            traits: Array.from(actor.items)
              .filter((item) => item.type === "trait")
              .map((item) => item.name),
            maxWounds: actor.system.status?.wounds?.max ?? 0,
            weaponSkill: actor.system.characteristics?.ws?.value ?? 0,
            strength: actor.system.characteristics?.s?.value ?? 0,
          },
        ]
      : [],
  );
}

export function getBossHealth(actor: BossActor): BossBarHealth {
  return {
    wounds: actor.system.status?.wounds?.value ?? 0,
    maxWounds: actor.system.status?.wounds?.max ?? 0,
    maxCriticals: actor.system.status?.criticalWounds?.max ?? 0,
    criticals: Array.from(actor.items).filter(
      (item) => item.type === "critical" && countsAsCritical(item.system?.wounds?.value),
    ).length,
  };
}
