// Parse in an inert document, then copy text only. Never carry card actions or event handlers
// into the fallback. Unrevealed secret sections must not become ordinary visible text.
export function chatCardText(content: string): string {
  const body = new DOMParser().parseFromString(content, "text/html").body;
  for (const element of body.querySelectorAll(
    "script, style, template, button, input, select, textarea, .chat-button, a[data-action], " +
      "[role='button'], .dice-tooltip, .applied-breakdown, " +
      ".secret:not(.revealed), [hidden], [aria-hidden='true']",
  )) {
    element.remove();
  }
  for (const image of body.querySelectorAll("img")) {
    image.replaceWith(body.ownerDocument.createTextNode(image.alt ? ` ${image.alt} ` : ""));
  }
  for (const element of body.querySelectorAll("br, p, div, li, tr, h1, h2, h3, h4, h5, h6")) {
    element.append(body.ownerDocument.createTextNode("\n"));
  }
  for (const cell of body.querySelectorAll("td, th")) {
    cell.append(body.ownerDocument.createTextNode(" "));
  }
  return (body.textContent ?? "")
    .split("\n")
    .map((line) => line.replace(/\s+/g, " ").trim())
    .filter(Boolean)
    .join("\n");
}

export function chatCardTextElement(text: string): HTMLParagraphElement {
  const paragraph = document.createElement("p");
  paragraph.textContent = text;
  paragraph.style.whiteSpace = "pre-line";
  return paragraph;
}
