import type {
  SettingPreference,
  SettingRegistration,
} from "../../../../types/settings-presets/SettingsPreset";
import type {
  SettingsInspection,
  SettingsResult,
} from "../../../../types/settings-presets/Protocol";
import { sameSettingValue } from "../../../functions/settings-presets/values";
import {
  automaticallyReloads,
  orderCampaignSettings,
  selectedWfrpTables,
  wfrpNeedsReload,
} from "../../../functions/settings-presets/wfrp";
import { settingValueToSource, validateSettingSource } from "./values";
import { coordinatePreferences } from "./coordination";

export function isSettingsNamespaceActive(namespace: string): boolean {
  return (
    namespace === "core" ||
    namespace === game?.system.id ||
    game?.modules.get(namespace)?.active === true
  );
}
export function inspectPreferences(
  owner: string,
  entries: SettingPreference[],
): SettingsInspection {
  if (!game?.ready || !game.user?.isGM)
    throw new Error("A ready GM session is required to inspect settings presets.");
  const plan = coordinatePreferences(owner, entries);
  const result: SettingsInspection = {
    changes: [],
    unchanged: [],
    skipped: [],
    failed: [],
    conflicts: plan.conflicts,
    excluded: plan.excluded,
    missingTables: [],
    requiresReload: false,
    automaticReload: false,
  };
  for (const entry of plan.entries) {
    const id = `${entry.namespace}.${entry.key}`;
    const setting = game.settings.settings?.get(id) as SettingRegistration | undefined;
    if (!isSettingsNamespaceActive(entry.namespace) || !setting || setting.scope !== "world") {
      result.skipped.push({
        id,
        reason: "World setting is unavailable or its namespace is not active",
      });
      continue;
    }
    try {
      validateSettingSource(setting, entry.value);
      if (game.system.id === "wfrp4e")
        result.missingTables.push(
          ...selectedWfrpTables(entry).filter(
            (id) =>
              !(
                game?.collections?.get("RollTable") as { get(id: string): unknown } | undefined
              )?.get(id),
          ),
        );
      const current = settingValueToSource(setting, game.settings.get(entry.namespace, entry.key));
      if (sameSettingValue(current, entry.value)) {
        result.unchanged.push(id);
        continue;
      }
      result.changes.push({
        ...entry,
        current,
        label: setting.name ? game.i18n.localize(setting.name) : id,
      });
      result.requiresReload ||=
        !!setting.requiresReload ||
        (game.system.id === "wfrp4e" && (wfrpNeedsReload(entry) || automaticallyReloads(entry)));
      result.automaticReload ||= game.system.id === "wfrp4e" && automaticallyReloads(entry);
    } catch (error) {
      result.failed.push({ id, reason: error instanceof Error ? error.message : String(error) });
    }
  }
  result.missingTables = [...new Set(result.missingTables)];
  return result;
}
let applying = false;
export async function applyPreferences(
  owner: string,
  entries: SettingPreference[],
): Promise<SettingsResult> {
  if (!game?.ready || !game.user?.isGM)
    throw new Error("A ready GM session is required to apply settings presets.");
  if (applying) throw new Error("A settings preset is already being applied.");
  applying = true;
  try {
    const inspection = inspectPreferences(owner, entries);
    const result: SettingsResult = {
      ...inspection,
      updated: [],
      blocked: !!(
        inspection.failed.length ||
        inspection.skipped.length ||
        inspection.conflicts.length ||
        inspection.missingTables.length
      ),
      requiresReload: false,
      automaticReload: false,
    };
    if (result.blocked) return result;
    for (const entry of orderCampaignSettings(inspection.changes, game.system.id)) {
      const id = `${entry.namespace}.${entry.key}`;
      try {
        if (!game.user?.isGM || !isSettingsNamespaceActive(entry.namespace))
          throw new Error("Preset permissions or availability changed.");
        // Another GM can resolve a conflict during an awaited write. Never continue with a stale choice.
        const latest = coordinatePreferences(owner, entries);
        const effective = latest.entries.find(
          (value) => value.namespace === entry.namespace && value.key === entry.key,
        );
        if (
          latest.conflicts.length ||
          !effective ||
          !sameSettingValue(effective.value, entry.value)
        )
          throw new Error("Preset choices changed; review the remaining settings again.");
        const setting = game.settings.settings?.get(id) as SettingRegistration | undefined;
        if (!setting || setting.scope !== "world") throw new Error("World setting is unavailable.");
        validateSettingSource(setting, entry.value);
        await game.settings.set(entry.namespace, entry.key, structuredClone(entry.value));
        result.requiresReload ||=
          !!setting.requiresReload ||
          (game.system.id === "wfrp4e" && (wfrpNeedsReload(entry) || automaticallyReloads(entry)));
        result.automaticReload ||= game.system.id === "wfrp4e" && automaticallyReloads(entry);
        if (
          !sameSettingValue(
            settingValueToSource(setting, game.settings.get(entry.namespace, entry.key)),
            entry.value,
          )
        )
          throw new Error("Foundry did not retain the complete preset value.");
        result.updated.push(id);
      } catch (error) {
        result.failed.push({ id, reason: error instanceof Error ? error.message : String(error) });
        break;
      }
    }
    return result;
  } finally {
    applying = false;
  }
}
