// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- The bridge extends Argon classes with no published TypeScript contracts.
// @ts-nocheck -- Argon and WFRP4e supply the bridge's dynamic panels and documents at runtime.

import { createArgonButtons } from "../enhancedcombathud/buttons";
import { getPaperDollQuickItems } from "./bridge-runtime";

export function createPaperDollArgonPanels(CoreHUD) {
  const ARGON = CoreHUD.ARGON;
  const { WFRPCombatItemButton } = createArgonButtons(CoreHUD);

  class PaperDollQuickItemsPanel extends ARGON.MAIN.ActionPanel {
    get label() {
      return "wfrp4e-compatibility-box.PaperDollArgon.Panel.QuickItems";
    }

    async _getButtons() {
      return getPaperDollQuickItems(this.actor).map((item) => new WFRPCombatItemButton({ item }));
    }
  }

  return { PaperDollQuickItemsPanel };
}
