import type { OptionalFeatureId } from "../../../types/module/OptionalFeature";
import { isModuleActive } from "../integrations/is-module-active";

interface OptionalFeatureDefinition {
  settingKey: string;
  targetModuleIds: readonly string[];
}

export const OPTIONAL_FEATURES = {
  simpleCalendar: {
    settingKey: "simpleCalendarEnabled",
    targetModuleIds: ["foundryvtt-simple-calendar-reborn"],
  },
  simpleTimekeeping: {
    settingKey: "simpleTimekeepingEnabled",
    targetModuleIds: ["simple-timekeeping"],
  },
  healthEstimate: { settingKey: "healthEstimateEnabled", targetModuleIds: ["healthEstimate"] },
  bossBar: {
    settingKey: "bossBarEnabled",
    targetModuleIds: ["bossbar"],
  },
  argonCombatHud: {
    settingKey: "argonCombatHudEnabled",
    targetModuleIds: ["enhancedcombathud"],
  },
  paperDoll: {
    settingKey: "paperDollEnabled",
    targetModuleIds: ["fvtt-paper-doll-ui"],
  },
  paperDollArgonBridge: {
    settingKey: "paperDollArgonBridgeEnabled",
    targetModuleIds: ["fvtt-paper-doll-ui", "enhancedcombathud"],
  },
} as const satisfies Record<OptionalFeatureId, OptionalFeatureDefinition>;

export function isOptionalFeatureAvailable(featureId: OptionalFeatureId): boolean {
  return OPTIONAL_FEATURES[featureId].targetModuleIds.every((moduleId) => isModuleActive(moduleId));
}
