import type { TimekeepingClass } from "../../../../types/integrations/calendars/Calendar";
import type { SettingRegistration } from "../../../../types/settings-presets/SettingsPreset";
import { timekeepingCalendar } from "../../../functions/calendars/imperial";
import { sameSettingValue } from "../../../functions/settings-presets/values";
import { isModuleActive } from "../is-module-active";
import { isOptionalFeatureEnabled } from "../../settings/is-optional-feature-enabled";
import { installImperialTimekeeping } from "./calendar";
import { TIMEKEEPING_MODULE_ID } from "./preset";

export function usesImperialCalendar(): boolean {
  if (game?.system.id !== "wfrp4e" || !isOptionalFeatureEnabled("simpleTimekeeping")) return false;
  const config = game.settings.get(TIMEKEEPING_MODULE_ID, "configuration") as {
    calendar?: string;
    customCalendar?: string;
  };
  if (config.calendar !== "custom") return false;
  try {
    const calendar = JSON.parse(config.customCalendar ?? "");
    const expected = timekeepingCalendar();
    return (
      calendar.id === expected.id &&
      ["years", "months", "days"].every((key) =>
        sameSettingValue(calendar[key], expected[key as keyof typeof expected]),
      )
    );
  } catch {
    return false;
  }
}

export function registerTimekeepingIntegration(): void {
  if (
    !isModuleActive(TIMEKEEPING_MODULE_ID) ||
    !isOptionalFeatureEnabled("simpleTimekeeping") ||
    game?.system.id !== "wfrp4e"
  )
    return;
  Hooks.once("setup", () => {
    // The native setting onChange redraws the clock but does not rebuild game.time.calendar.
    const setting = game?.settings.settings?.get(`${TIMEKEEPING_MODULE_ID}.configuration`) as
      | SettingRegistration
      | undefined;
    if (setting) setting.requiresReload = true;
  });
  const installed = new WeakSet<object>();
  Hooks.on("initSimpleTimekeeping", (value) => {
    const clock = value as TimekeepingClass;
    if (
      !clock?.prototype ||
      typeof clock.prototype.getFullDateText !== "function" ||
      typeof clock.prototype.timestamp !== "function" ||
      typeof clock.pickDateTime !== "function" ||
      !game?.time?.calendar ||
      installed.has(clock)
    )
      return;
    installed.add(clock);
    // This hook is emitted after Foundry initializes its calendar, before ST&C renders.
    const loadedImperialCalendar = usesImperialCalendar();
    installImperialTimekeeping(
      clock,
      game.time,
      () => loadedImperialCalendar && usesImperialCalendar(),
    );
  });
}
