import { MODULE_ID } from "../../../constants";
import { CALENDAR_CATALOG, holidayDateLabel } from "../../../functions/calendars/content";
import { isOptionalFeatureEnabled } from "../../settings/is-optional-feature-enabled";
import { escapePresetHtml } from "../../settings/preset-runtime/presentation";
import { notifyError } from "../../notifications/notify-user";
import { importCalendarContent, inspectCalendarContent } from "./content";

export async function reviewCalendarContent(): Promise<void> {
  if (!game?.ready || !game.user?.isGM) throw new Error("A ready GM session is required.");
  const escape = escapePresetHtml;
  const choice = await foundry.applications.api.DialogV2.wait({
    window: { title: "WFRP Calendar Content" },
    position: { width: 720 },
    content: `<p>Import sourced WFRP observances and Ubersreik history. Holidays are visible to players; the historical almanac and dated historical/scenario events are GM-only. Existing notes, dates and text are preserved. No macros or chat reminders are enabled.</p><table><thead><tr><th>Observance</th><th>Date</th><th>Region</th></tr></thead><tbody>${CALENDAR_CATALOG.holidays.map((h) => `<tr><td>${escape(h.name)}</td><td>${escape(holidayDateLabel(h))}</td><td>${escape(h.region)}</td></tr>`).join("")}</tbody></table><p><strong>Ubersreik history:</strong> ${CALENDAR_CATALOG.history.length} sourced entries with year, range and uncertainty labels. Year-only history stays in the reference journal. Eight dated events are included without annual repetition: the provisional deposition date (5 Nachexen 2512 IC) and seven labelled scenario defaults from The Blessings that Drew Blood.</p><p><strong>Middenheim Carnival:</strong> included with holidays on 1–8 Brauzeit, using the older published default. Later books leave its seasonal timing flexible; you can adjust the imported event.</p>`,
    buttons: [
      { action: "both", label: "Holidays + History", default: true },
      { action: "holidays", label: "Holidays Only" },
      { action: "history", label: "History Only" },
      { action: "close", label: "Close" },
    ],
    rejectClose: false,
  });
  if (!choice || choice === "close") return;
  const options = {
    holidays: choice === "both" || choice === "holidays",
    history: choice === "both" || choice === "history",
  };
  const plan = inspectCalendarContent(options);
  const confirm = await foundry.applications.api.DialogV2.wait({
    window: { title: "Import WFRP Calendar Content" },
    position: { width: 650 },
    content: `<p>${plan.targets.calendarId ? "Simple Calendar notes" : !plan.targets.timekeeping ? "GM reference journal" : ""}${plan.targets.calendarId && plan.targets.timekeeping ? " and " : ""}${plan.targets.timekeeping ? "ST&C events" : ""}. Existing documents keep their text and dates. Newly enabled calendar support may be attached to managed notes. Reload afterward to refresh both calendar displays.</p><ul>${plan.entries.map((e) => `<li><strong>${escape(e.name)}</strong>: ${escape(e.status)}</li>`).join("")}</ul>`,
    buttons: [
      { action: "import", label: "Import Content", default: true },
      { action: "cancel", label: "Cancel" },
    ],
    rejectClose: false,
  });
  if (confirm !== "import") return;
  const result = await importCalendarContent(options, plan.targets);
  ui?.notifications?.info(
    `Calendar content: ${result.created.length} created, ${result.connected.length} connected, ${result.skipped.length} preserved or skipped. Reload to refresh the calendars.`,
  );
}

export function registerCalendarContent(): void {
  if (
    game?.system.id !== "wfrp4e" ||
    !(isOptionalFeatureEnabled("simpleCalendar") || isOptionalFeatureEnabled("simpleTimekeeping"))
  )
    return;
  Hooks.once("setup", () =>
    game?.settings.registerMenu(MODULE_ID, "calendarContent", {
      name: "WFRP calendar content",
      label: "Import WFRP Calendar Content",
      hint: "Review Imperial and Ubersreik holidays, including Middenheim Carnival, and import the historical almanac.",
      icon: "fa-solid fa-calendar-days",
      restricted: true,
      type: class extends foundry.applications.api.ApplicationV2 {
        override async render(): Promise<this> {
          try {
            await reviewCalendarContent();
          } catch (error) {
            notifyError(error instanceof Error ? error.message : String(error), error);
          }
          return this;
        }
      },
    }),
  );
}
