import type { PresetMetadata } from "../../../types/settings-presets/Protocol";

/** Metadata is separate from native setting values, so existing namespace files remain portable. */
export function parsePresetMetadata(
  source: unknown,
  namespaces: string[],
): Record<string, PresetMetadata> {
  if (!source || typeof source !== "object" || Array.isArray(source))
    throw new Error("Settings preset metadata must be an object.");
  return Object.fromEntries(
    Object.entries(source).map(([namespace, value]) => {
      if (!namespaces.includes(namespace))
        throw new Error(`Metadata has no settings source: ${namespace}`);
      if (!value || typeof value !== "object" || Array.isArray(value))
        throw new Error(`Invalid metadata for ${namespace}`);
      const metadata = value as Record<string, unknown>;
      for (const [key, entry] of Object.entries(metadata)) {
        if (
          key === "promptOnStartup"
            ? typeof entry !== "boolean"
            : !["title", "description"].includes(key) || typeof entry !== "string"
        )
          throw new Error(`Invalid preset metadata: ${namespace}.${key}`);
      }
      return [namespace, metadata as PresetMetadata];
    }),
  );
}
