import type { SplatterConfigurationResult } from "../../../../types/integrations/splatter/Configuration";
import { applySettingsPreset, inspectSettingsPreset } from "../../settings/presets/engine";
import { getSettingsPreset } from "../../settings/presets/definitions";
import { SPLATTER_BLOOD_COLORS_SETTING, SPLATTER_MODULE_ID } from "./constants";

export function matchesSplatterConfiguration(): boolean {
  const inspection = inspectSettingsPreset(getSettingsPreset(SPLATTER_MODULE_ID));
  if (inspection.unavailable.length) throw new Error(inspection.unavailable.join("; "));
  return inspection.changes.length === 0;
}

export async function configureSplatter(): Promise<SplatterConfigurationResult> {
  const preset = getSettingsPreset(SPLATTER_MODULE_ID);
  await applySettingsPreset(preset);
  return {
    automaticBloodColors: game?.settings.get(SPLATTER_MODULE_ID, "useBloodsheet") === true,
    bloodColorCount: Object.keys(
      game?.settings.get(SPLATTER_MODULE_ID, SPLATTER_BLOOD_COLORS_SETTING) as object,
    ).length,
    speciesPath: preset.values["creatureType"] as string,
  };
}
