import type {
  TimekeepingClass,
  TimekeepingCalendar,
  TimekeepingComponents,
} from "../../../../types/integrations/calendars/Calendar";
import {
  imperialDate,
  imperialDateText,
  imperialTimestamp,
  IMPERIAL_MONTHS,
} from "../../../functions/calendars/imperial";
import { escapePresetHtml } from "../../settings/preset-runtime/presentation";

/** Wrap only date-facing behavior; native time advancement and event storage stay in seconds. */
export function installImperialTimekeeping(
  clock: TimekeepingClass,
  time: { worldTime: number; calendar: TimekeepingCalendar },
  enabled: () => boolean,
): void {
  const toTimestamp = (value?: TimekeepingComponents | number) =>
    value === undefined
      ? time.worldTime
      : typeof value === "number"
        ? value
        : time.calendar.componentsToTime(value);
  const originalDate = clock.prototype.getFullDateText;
  const originalTimestamp = clock.prototype.timestamp;
  const originalPicker = clock.pickDateTime;
  clock.prototype.getFullDateText = function (value) {
    return enabled() ? imperialDateText(toTimestamp(value)) : originalDate.call(this, value);
  };
  clock.prototype.timestamp = function (value) {
    return enabled()
      ? imperialDateText(toTimestamp(value), true)
      : originalTimestamp.call(this, value);
  };
  clock.pickDateTime = async function (value, format = "timestamp") {
    if (!enabled()) return originalPicker.call(this, value, format);
    const date = imperialDate(toTimestamp(value));
    const field = (name: string, label: string, value: number, min?: number, max?: number) =>
      `<label>${label}<input type="number" name="${name}" value="${value}" required step="1" ${min === undefined ? "" : `min="${min}"`} ${max === undefined ? "" : `max="${max}"`}></label>`;
    const options = IMPERIAL_MONTHS.map(
      (m, i) =>
        `<option value="${i}" ${i === date.month ? "selected" : ""}>${escapePresetHtml(m.name)}</option>`,
    ).join("");
    const result = await foundry.applications.api.DialogV2.input({
      window: { title: "Pick Date and Time — WFRP Imperial Calendar" },
      content: `${field("year", "Year (IC)", date.year)}<label>Month<select name="month">${options}</select></label>${field("day", "Day", date.day + 1, 1, 33)}${field("hour", "Hour", date.hour, 0, 23)}${field("minute", "Minute", date.minute, 0, 59)}${field("second", "Second", date.second, 0, 59)}`,
      ok: { label: "Confirm" },
      rejectClose: false,
    });
    if (!result) return null;
    try {
      if (Object.values(result).some((v) => v === "" || v === null))
        throw new Error("Complete every date and time field.");
      const timestamp = imperialTimestamp({
        year: Number(result["year"]),
        month: Number(result["month"]),
        day: Number(result["day"]) - 1,
        hour: Number(result["hour"]),
        minute: Number(result["minute"]),
        second: Number(result["second"]),
      });
      return format === "timestamp" ? timestamp : time.calendar.timeToComponents(timestamp);
    } catch (error) {
      ui?.notifications?.error(error instanceof Error ? error.message : String(error));
      return null;
    }
  };
  // ST&C's native weekday calculation includes the six intercalary days. Correct its
  // components as well as the labels, so the mini calendar and other consumers agree.
  const calendar = time.calendar;
  const originalComponents = calendar.timeToComponents;
  calendar.timeToComponents = function (timestamp = 0) {
    const result = originalComponents.call(this, timestamp);
    return enabled() ? { ...result, dayOfWeek: imperialDate(timestamp).weekday } : result;
  };
}
