import type { SettingPreference } from "../../../types/settings-presets/SettingsPreset";

/** WFRP schedules a reload when group advantage changes, so this write must be last. */
export function orderCampaignSettings(
  entries: SettingPreference[],
  systemId: string,
): SettingPreference[] {
  if (systemId !== "wfrp4e") return [...entries];
  return [...entries].sort(
    (a, b) => Number(automaticallyReloads(a)) - Number(automaticallyReloads(b)),
  );
}

export function automaticallyReloads({ namespace, key }: SettingPreference): boolean {
  return namespace === "wfrp4e" && key === "useGroupAdvantage";
}

/** These startup-only settings do not all declare requiresReload in their registrations. */
export function wfrpNeedsReload({ namespace, key }: SettingPreference): boolean {
  return (
    (namespace === "wfrp4e" && ["homebrew", "customCursor"].includes(key)) ||
    (namespace === "wfrp4e-rnhd" && ["showClock", "syncClock"].includes(key))
  );
}

export function selectedWfrpTables({ namespace, key, value }: SettingPreference): string[] {
  if (namespace !== "wfrp4e" || key !== "tableSettings" || !value || typeof value !== "object")
    return [];
  return [
    ...new Set(Object.values(value).flatMap((ids) => String(ids).split(",").filter(Boolean))),
  ];
}
